@dataclass
class Token:
    type: str
    value: str
    line: int
    col: int

def expect(self, ttype: str) -> Token:
    tok = self.peek()
    if tok.type != ttype:
        raise SyntaxError_(
            f"Syntax Error at line {tok.line}: expected {ttype}, "
            f"found {tok.type} ({tok.value!r})"
        )
    return self.advance()

