from dataclasses import dataclass
from typing import List
from ds_pipeline_dsl.ast_nodes import (
    PipelineNode, LoadStmt, CleanStmt, SelectStmt, DropStmt,
    SplitStmt, TrainStmt, EvaluateStmt
)
from ds_pipeline_dsl.semantic import SymbolTable

@dataclass
class IRInstruction:
    op: str
    args: dict

def lower_to_ir(pipeline_ast: PipelineNode, symbol_table: SymbolTable) -> List[IRInstruction]:
    ir = []
    for stmt in pipeline_ast.statements:
        if isinstance(stmt, LoadStmt):
            ir.append(IRInstruction(op="OP_LOAD", args={"filename": stmt.filename, "line": stmt.line}))
        elif isinstance(stmt, CleanStmt):
            ir.append(IRInstruction(op="OP_CLEAN", args={"strategy": stmt.strategy, "line": stmt.line}))
        elif isinstance(stmt, SelectStmt):
            ir.append(IRInstruction(op="OP_SELECT", args={"columns": stmt.columns, "line": stmt.line}))
        elif isinstance(stmt, DropStmt):
            ir.append(IRInstruction(op="OP_DROP", args={"columns": stmt.columns, "line": stmt.line}))
        elif isinstance(stmt, SplitStmt):
            ir.append(IRInstruction(op="OP_SPLIT", args={"name": stmt.name, "percent": stmt.percent, "line": stmt.line}))
        elif isinstance(stmt, TrainStmt):
            ir.append(IRInstruction(op="OP_TRAIN", args={"model_name": stmt.model_name, "algorithm": stmt.algorithm, "line": stmt.line}))
        elif isinstance(stmt, EvaluateStmt):
            ir.append(IRInstruction(op="OP_EVAL", args={"model_name": stmt.model_name, "line": stmt.line}))
    return ir

from typing import List
from ds_pipeline_dsl.ir import IRInstruction

def execute(ir_list: List[IRInstruction]) -> List[str]:
    trace = []
    for instr in ir_list:
        if instr.op == "OP_LOAD":
            trace.append(f"Loaded {instr.args['filename']}")
        elif instr.op == "OP_CLEAN":
            trace.append(f"Cleaned using {instr.args['strategy']}")
        elif instr.op == "OP_SELECT":
            cols = ", ".join(instr.args["columns"])
            trace.append(f"Selected columns: {cols}")
        elif instr.op == "OP_DROP":
            cols = ", ".join(instr.args["columns"])
            trace.append(f"Dropped columns: {cols}")
        elif instr.op == "OP_SPLIT":
            percent = instr.args["percent"]
            if percent == int(percent):
                percent = int(percent)
            trace.append(f"Defined split '{instr.args['name']}' = {percent}%")
        elif instr.op == "OP_TRAIN":
            trace.append(f"Trained model '{instr.args['model_name']}' using {instr.args['algorithm']}")
        elif instr.op == "OP_EVAL":
            trace.append(f"Evaluated model '{instr.args['model_name']}' (simulated accuracy trace)")
        else:
            trace.append(f"Unknown instruction: {instr.op}")
    return trace

def _snapshot_state(cleaning_history: List[str],
                    selected_columns: Optional[Tuple[str, ...]],
                    dropped_columns: set,
                    splits: dict) -> Tuple[Tuple[str, ...], Optional[Tuple[str, ...]], frozenset, Tuple[Tuple[str, float], ...]]:
    return (
        tuple(cleaning_history),
        selected_columns,
        frozenset(dropped_columns),
        tuple(sorted(splits.items()))
    )
